<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Footstep invoice</title><style>
*{box-sizing:border-box}body{margin:0;font:14px/1.5 Arial,sans-serif;background:#f2f6f4;color:#18372e;padding:32px 16px}.invoice{max-width:960px;margin:auto;background:#fff;padding:32px;border:1px solid #e0e8e3;border-radius:16px;box-shadow:0 8px 32px #18372e08}.admin-invoice-controls{display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:16px;background:#f5f8f6;border:1px solid #e2e9e5;border-radius:12px;margin-bottom:12px}.admin-invoice-controls strong{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#64786e;width:100%}.admin-invoice-controls form{margin:0}.invoice-button{display:inline-flex;align-items:center;justify-content:center;min-height:42px;padding:10px 16px;font:600 13px/1.3 Arial,sans-serif;text-decoration:none;border:1px solid #d7e2db;border-radius:8px;background:#fff;color:#18372e;cursor:pointer}.invoice-button:hover{filter:brightness(.96)}.invoice-button:focus-visible{outline:3px solid #93c5b0;outline-offset:2px}.invoice-button.primary{background:#087d50;border-color:#087d50;color:white}.invoice-button.danger{background:#fff2f2;border-color:#f3cdcd;color:#ac2929}.print-button{margin-top:20px}table{font-size:13px}th,td{padding:10px 6px}td:nth-child(4),td:nth-child(5),td:nth-child(6){white-space:nowrap}td:nth-child(3){overflow-wrap:anywhere}header{gap:20px}header h2{font-size:23px}address{margin:0;max-width:55%}
@media(max-width:600px){body{padding:12px 8px}.invoice{padding:18px 14px;border-radius:12px}.admin-invoice-controls{padding:12px;gap:8px}.admin-invoice-controls>a{width:100%}.admin-invoice-controls form{flex:1;display:flex!important}.admin-invoice-controls button{width:100%;font-size:12px;padding:10px 8px}.order-invoice-document header{flex-wrap:wrap;padding:18px 0!important;gap:10px}.order-invoice-document header h2{font-size:20px}.order-invoice-document header>div:last-child{font-size:12px}.order-invoice-document table thead{display:none}.order-invoice-document table,.order-invoice-document tbody{display:block}.order-invoice-document tbody tr{display:grid;grid-template-columns:48px 1fr 1fr;gap:10px;padding:16px 0}.order-invoice-document td{display:block;padding:0!important;width:auto!important}.order-invoice-document td:nth-child(1){display:none}.order-invoice-document td:nth-child(2){grid-column:1;grid-row:1}.order-invoice-document td:nth-child(3){grid-column:2/4;grid-row:1;font-size:13px}.order-invoice-document td:nth-child(4),.order-invoice-document td:nth-child(5),.order-invoice-document td:nth-child(6){text-align:left!important;font-size:12px}.order-invoice-document td:nth-child(4):before{content:'Qty';display:block;color:#718078;font-size:10px}.order-invoice-document td:nth-child(5):before{content:'Unit price';display:block;color:#718078;font-size:10px}.order-invoice-document td:nth-child(6):before{content:'Total';display:block;color:#718078;font-size:10px}.print-button{width:100%}}
