/* Shared invoice admin actions: scoped, aligned, and provider-specific. */
.admin-invoice-controls{display:block;padding:18px;background:#f7faf9;border:1px solid #dce8e2;border-radius:16px}
.admin-invoice-controls .admin-controls-heading{display:block;width:auto;margin:0 0 14px;font:700 11px/1.5 Arial,sans-serif;letter-spacing:.09em;color:#526d61}
.admin-invoice-action-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;align-items:start}
.admin-invoice-action-grid>.admin-action-manage{grid-column:1/-1}
.admin-invoice-action-grid .steadfast-account-buttons{display:contents!important}
.admin-invoice-action-grid .steadfast-account-buttons>strong,.admin-invoice-action-grid [data-courier-result]{grid-column:1/-1}
.admin-invoice-action-grid [data-courier-result]:empty{display:none}
.admin-invoice-action-grid form{display:flex!important;flex-direction:column;align-items:stretch;gap:7px;margin:0;min-width:0}
.admin-invoice-action-grid :is(.invoice-button,.btn){display:flex;align-items:center;justify-content:center;width:100%;min-width:0;min-height:52px;margin:0;padding:13px 14px;border:1px solid transparent;border-radius:11px;font:700 13px/1.5 Arial,sans-serif;text-align:center;text-decoration:none;white-space:normal;overflow-wrap:anywhere;cursor:pointer;transition:box-shadow .15s,filter .15s}
.admin-invoice-action-grid .admin-action-manage{background:#eaf1ff;color:#214f92;border-color:#c5d6f3}
.admin-invoice-action-grid [data-courier-send]{background:#e7f5ef;color:#146148;border-color:#afd8c5}
.admin-invoice-action-grid [data-courier-send]:nth-of-type(even){background:#fff1e4;color:#8b431d;border-color:#edcbb1}
.admin-invoice-action-grid form[action*="carrybee"] button,.admin-invoice-action-grid a[href*="carrybee"]{background:#fff4cf;color:#765414;border-color:#e8cf81}
.admin-invoice-action-grid .admin-action-cancel button{background:#fff0f2;color:#a53149;border-color:#edbfc8}
.admin-invoice-action-grid form>small{display:block;padding:0 4px;font:12px/1.5 Arial,sans-serif;color:#526c60;text-align:center;overflow-wrap:anywhere}
.admin-invoice-action-grid :is(.invoice-button,.btn):hover{filter:brightness(.97);box-shadow:0 3px 9px #173b4310}
.admin-invoice-action-grid :is(.invoice-button,.btn):focus-visible{outline:3px solid #4186b5;outline-offset:3px}
.admin-invoice-action-grid :is(button:disabled,[aria-disabled="true"]){background:#edf1ef;color:#5a6962;border-color:#d6dfda;cursor:not-allowed;filter:none;box-shadow:none}
@media(max-width:600px){.admin-invoice-controls{padding:14px}.admin-invoice-action-grid{grid-template-columns:minmax(0,1fr);gap:10px}.admin-invoice-action-grid>.admin-action-manage{grid-column:auto}.admin-invoice-action-grid :is(.invoice-button,.btn){min-height:50px;font-size:13px}.admin-invoice-action-grid form{flex:initial}}
@media(prefers-reduced-motion:reduce){.admin-invoice-action-grid :is(.invoice-button,.btn){transition:none}}
